param([string]$Path="",[string]$WorkspaceRoot="",[string]$RepoMapPath="",[switch]$SelfTest)
$ErrorActionPreference='Stop'
Import-Module (Join-Path $PSScriptRoot 'lib\MorphospacePlannedPublication.psm1') -Force
function Write-Json($Path,$Value){$parent=Split-Path -Parent $Path;if($parent-and-not(Test-Path $parent)){New-Item -ItemType Directory $parent|Out-Null};[IO.File]::WriteAllText($Path,($Value|ConvertTo-Json -Depth 32)+"`n",[Text.UTF8Encoding]::new($false))}
function Hash($Path){(Get-FileHash $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Invoke-FixtureGit($Repo,[string[]]$GitArgs){$git=(Get-Command git -CommandType Application -ErrorAction Stop).Source;$o=@(& $git -C $Repo @GitArgs 2>&1);if($LASTEXITCODE){throw "git $($GitArgs-join' ') failed: $($o-join' ')"};if($o.Count){([string]($o|Select-Object -Last 1)).Trim()}else{''}}
function Expect-Reject([scriptblock]$Action,[string]$Name){$ok=$false;try{&$Action|Out-Null}catch{$ok=$true};if(-not$ok){throw "Damaged case '$Name' was accepted."}}
function Clone-Object($o){$o|ConvertTo-Json -Depth 32|ConvertFrom-Json}
if($SelfTest){
 $root=Join-Path ([IO.Path]::GetTempPath()) ('planned-publication-'+[guid]::NewGuid().ToString('N'));$ws=Join-Path $root 'planning\project\morphospace';$src=Join-Path $root 'source';$planning=Split-Path (Split-Path $ws -Parent) -Parent
 try{
  foreach($repo in @($src,$planning)){New-Item -ItemType Directory $repo -Force|Out-Null;Invoke-FixtureGit $repo @('init','-q');Invoke-FixtureGit $repo @('config','user.email','fixture@example.invalid');Invoke-FixtureGit $repo @('config','user.name','Fixture');Invoke-FixtureGit $repo @('checkout','-q','-b','main');[IO.File]::WriteAllText((Join-Path $repo 'base.txt'),"base`n");Invoke-FixtureGit $repo @('add','.');Invoke-FixtureGit $repo @('commit','-q','-m','base')}
  $srcOld=Invoke-FixtureGit $src @('rev-parse','HEAD');[IO.File]::WriteAllText((Join-Path $src 'carried.txt'),"blocked carried source`n");Invoke-FixtureGit $src @('add','.');Invoke-FixtureGit $src @('commit','-q','-m','carried blocked unit');$srcCarried=Invoke-FixtureGit $src @('rev-parse','HEAD');[IO.File]::WriteAllText((Join-Path $src 'trigger.txt'),"accepted trigger`n");Invoke-FixtureGit $src @('add','.');Invoke-FixtureGit $src @('commit','-q','-m','trigger unit');$srcFinal=Invoke-FixtureGit $src @('rev-parse','HEAD')
  $planOld=Invoke-FixtureGit $planning @('rev-parse','HEAD');New-Item -ItemType Directory $ws -Force|Out-Null;[IO.File]::WriteAllText((Join-Path $ws 'prepared.txt'),"prepared workflow state`n");Invoke-FixtureGit $planning @('add','.');Invoke-FixtureGit $planning @('commit','-q','-m','prepare publication');$planPrepared=Invoke-FixtureGit $planning @('rev-parse','HEAD');New-Item -ItemType Directory (Join-Path $ws 'receipts') -Force|Out-Null
  Write-Json (Join-Path $ws 'trigger-status.json') ([ordered]@{unit_id='trigger-unit';status='accepted'});Write-Json (Join-Path $ws 'carried-status.json') ([ordered]@{unit_id='carried-unit';status='blocked'});Write-Json (Join-Path $ws 'prepared-event.json') ([ordered]@{event_id='trigger-unit-push-prepared-0001';event_type='commit'})
  $plan=[ordered]@{schema='rusty.morphospace.workflow.push_bundle_plan.v1';bundle_id='trigger-unit-push-bundle';project_id='test-project';unit_ids=@('trigger-unit');prepared_at='2026-07-17T10:00:00Z';dependency_order=@('source-repo','planning-repo');repositories=@([ordered]@{repo_id='source-repo';role='source';branch='main';commit=$srcFinal;upstream='origin/main';ahead=0;behind=0},[ordered]@{repo_id='planning-repo';role='planning';branch='main';commit=$planPrepared;upstream='origin/main';ahead=0;behind=0});source_first=$true;planning_last=$true;execution='not-performed';force_push_allowed=$false};Write-Json (Join-Path $ws 'receipts\plan.json') $plan
  $executed=[ordered]@{schema='rusty.morphospace.workflow.executed_push_receipt.v1';receipt_id='executed-receipt';bundle_id=$plan.bundle_id;project_id=$plan.project_id;unit_ids=@('trigger-unit');prepared_plan_id=$plan.bundle_id;started_at='2026-07-17T10:01:00Z';finished_at='2026-07-17T10:02:00Z';status='validated-pushed';execution='externally-performed';dependency_order=@('source-repo','planning-repo');execution_order=@('source-repo','planning-repo');repositories=@([ordered]@{repo_id='source-repo';old_revision=$srcOld;new_revision=$srcFinal;observed_remote_revision=$srcFinal},[ordered]@{repo_id='planning-repo';old_revision=$planOld;new_revision='0000000000000000000000000000000000000000';observed_remote_revision='0000000000000000000000000000000000000000'});force_push_used=$false;remote_readback_complete=$true;failure=$null};Write-Json (Join-Path $ws 'receipts\executed.json') $executed
  [IO.File]::WriteAllText((Join-Path $ws 'publication-finalized.txt'),"transport closure`n");Invoke-FixtureGit $planning @('add','.');Invoke-FixtureGit $planning @('commit','-q','-m','publication finalization');$planFinal=Invoke-FixtureGit $planning @('rev-parse','HEAD');$executed.repositories[1].new_revision=$planFinal;$executed.repositories[1].observed_remote_revision=$planFinal;Write-Json (Join-Path $ws 'receipts\executed.json') $executed
  # The executed receipt is transport evidence and is committed by the finalization commit.
  Invoke-FixtureGit $planning @('add','.');Invoke-FixtureGit $planning @('commit','--amend','-q','--no-edit');$planFinal=Invoke-FixtureGit $planning @('rev-parse','HEAD');$executed.repositories[1].new_revision=$planFinal;$executed.repositories[1].observed_remote_revision=$planFinal;Write-Json (Join-Path $ws 'receipts\executed.json') $executed;Invoke-FixtureGit $planning @('add','.');Invoke-FixtureGit $planning @('commit','--amend','-q','--no-edit');$planFinal=Invoke-FixtureGit $planning @('rev-parse','HEAD')
  # Avoid a self-referential final hash in the synthetic executed document: live accounting binds the actual final and readback below.
  $executed.repositories[1].new_revision=$planFinal;$executed.repositories[1].observed_remote_revision=$planFinal;Write-Json (Join-Path $ws 'receipts\executed.json') $executed
  $srcPaths=@('carried.txt','trigger.txt');$planPreparedPaths=@('project/morphospace/prepared.txt');$planFinalPaths=@(Invoke-FixtureGit $planning @('diff-tree','--no-commit-id','--name-only','-r',$planFinal) -split"`n")
  $account=[ordered]@{schema='rusty.morphospace.workflow.planned_publication_accounting.v1';accounting_id='publication-accounting';project_id='test-project';bundle_id=$plan.bundle_id;trigger_unit_id='trigger-unit';prepared_plan=[ordered]@{path='receipts/plan.json';sha256=Hash (Join-Path $ws 'receipts\plan.json')};prepared_event=[ordered]@{event_id='trigger-unit-push-prepared-0001';path='prepared-event.json';sha256=Hash (Join-Path $ws 'prepared-event.json')};executed_push_receipt=[ordered]@{path='receipts/executed.json';sha256=Hash (Join-Path $ws 'receipts\executed.json')};chronology=[ordered]@{prepared_at='2026-07-17T10:00:00Z';push_started_at='2026-07-17T10:01:00Z';push_finished_at='2026-07-17T10:02:00Z';accounted_at='2026-07-17T10:03:00Z'};dependency_order=@('source-repo','planning-repo');execution_order=@('source-repo','planning-repo');repositories=@([ordered]@{repo_id='source-repo';role='source';branch='main';upstream='origin/main';old_revision=$srcOld;prepared_revision=$srcFinal;final_revision=$srcFinal;remote_readback_revision=$srcFinal;source_first=$true;planning_last=$false;fast_forward_verified=$true;force_push_used=$false;worktree_clean=$true;units=@([ordered]@{unit_id='carried-unit';role='carried-unit';status_at_publication='blocked';status_evidence=[ordered]@{path='carried-status.json';sha256=Hash (Join-Path $ws 'carried-status.json')};no_acceptance_claim=$true},[ordered]@{unit_id='trigger-unit';role='triggering-unit';status_at_publication='accepted';status_evidence=[ordered]@{path='trigger-status.json';sha256=Hash (Join-Path $ws 'trigger-status.json')};no_acceptance_claim=$false});commits=@([ordered]@{revision=$srcCarried;role='carried-unit';unit_id='carried-unit';changed_paths=@('carried.txt')},[ordered]@{revision=$srcFinal;role='triggering-unit';unit_id='trigger-unit';changed_paths=@('trigger.txt')});allowed_finalization_paths=@()},[ordered]@{repo_id='planning-repo';role='planning-transport';branch='main';upstream='origin/main';old_revision=$planOld;prepared_revision=$planPrepared;final_revision=$planFinal;remote_readback_revision=$planFinal;source_first=$false;planning_last=$true;fast_forward_verified=$true;force_push_used=$false;worktree_clean=$true;units=@([ordered]@{unit_id='trigger-unit';role='triggering-unit';status_at_publication='accepted';status_evidence=[ordered]@{path='trigger-status.json';sha256=Hash (Join-Path $ws 'trigger-status.json')};no_acceptance_claim=$false});commits=@([ordered]@{revision=$planPrepared;role='triggering-unit';unit_id='trigger-unit';changed_paths=$planPreparedPaths},[ordered]@{revision=$planFinal;role='workflow-publication-finalization';unit_id=$null;changed_paths=$planFinalPaths});allowed_finalization_paths=@('project/morphospace/receipts/','project/morphospace/publication-finalized.txt')});workspace_transition=[ordered]@{pending_push_bundle_before=$plan.bundle_id;pending_push_bundle_after=$null};force_push_used=$false;remote_readback_complete=$true;failure=$null};$accountPath=Join-Path $ws 'receipts\accounting.json';Write-Json $accountPath $account
  $account.repositories[1].allowed_finalization_paths=@('project/morphospace/');Write-Json $accountPath $account
  Test-MorphospacePlannedPublicationDocument $accountPath $ws|Out-Null
  foreach($case in @('bundle','unit','hash','evidence','order','missing-commit','extra-commit','reordered-commit','status','acceptance','source-prepared','planning-ancestry','suffix-path','readback','force','chronology')){$bad=Clone-Object $account;switch($case){'bundle'{$bad.bundle_id='wrong-bundle'}'unit'{$bad.trigger_unit_id='wrong-unit'}'hash'{$bad.prepared_plan.sha256=('0'*64)}'evidence'{$bad.repositories[0].units[0].status_evidence.sha256=('0'*64)}'order'{$bad.execution_order=@('planning-repo','source-repo')}'missing-commit'{$bad.repositories[0].commits=@($bad.repositories[0].commits|Select-Object -Last 1)}'extra-commit'{$bad.repositories[0].commits+=Clone-Object $bad.repositories[0].commits[-1]}'reordered-commit'{$bad.repositories[0].commits=@($bad.repositories[0].commits[1],$bad.repositories[0].commits[0])}'status'{$bad.repositories[0].units[0].status_at_publication='accepted'}'acceptance'{$bad.repositories[0].units[0].no_acceptance_claim=$false}'source-prepared'{$bad.repositories[0].prepared_revision=$srcOld}'planning-ancestry'{$bad.repositories[1].prepared_revision=$srcFinal}'suffix-path'{$bad.repositories[1].commits[1].changed_paths=@('product.txt')}'readback'{$bad.repositories[0].remote_readback_revision=$srcOld}'force'{$bad.force_push_used=$true}'chronology'{$bad.chronology.accounted_at='2026-07-17T09:00:00Z'}};$badPath=Join-Path $ws "receipts\bad-$case.json";Write-Json $badPath $bad;Expect-Reject {Test-MorphospacePlannedPublicationDocument $badPath $ws} $case}
  "Planned-publication accounting self-test passed."
 }finally{if(Test-Path $root){Remove-Item -Recurse -Force $root}}
 exit 0
}
